style.css:
@-moz-document url-prefix("https://www.roblox.com/") {
/* Roblox Play button */
button.btn-common-play-game-lg[data-testid="play-button"] {
    background-color: #02B757 !important;
    border-color: #02B757 !important;
    color: white !important;
}

/* Play icon */
button.btn-common-play-game-lg[data-testid="play-button"] .icon-common-play {
    filter: brightness(0) invert(1) !important;
}

/* Hover */
button.btn-common-play-game-lg[data-testid="play-button"]:hover {
    background-color: #02B757 !important;
    border-color: #02B757 !important;
}

/* RoPro Random Server button */
#ropro-quick-random-server-button,
.random-server-button {
    background: #02B757 !important;
    background-color: #02B757 !important;
    border-color: #02B757 !important;
    color: white !important;
}
}
